@r2.c1 w.request.constraint request=$r2 on=place attribute=drawn.relation value=beside words="beside the boy in the purple jacket" operator=relation phase=result open_value=true
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=drawn.colour value=yellow operator=eq phase=selector
@r2.c3 w.request.constraint request=$r2 on=place attribute=drawn.anchor value="the boy in the purple jacket" operator=relation phase=selector
@r2.c4 w.request.constraint request=$r2 on=place attribute=drawn.restore value=original operator=eq phase=result words="back to his original place"

